const body = $input.first().json.body;

if (!body || Object.keys(body).length === 0) {
  throw new Error('Empty or missing payload body');
}

const chatId = body.chatId || body.telegram_chat_id || body.chat_id || null;
const payloadStr = JSON.stringify(body, null, 2);

const chatInput = "Analyze the following lead payload and classify it:\n\n```\n" + payloadStr + "\n```";

return [{
  json: {
    chatInput: chatInput,
    chatId: chatId,
    rawPayload: body
  }
}];

const output = $input.first().json.output;

const classification = output.clasificacion || 'cold';
const score = output.puntuacion || 0;

const icons = { hot: '🔥', warm: '⚡', cold: '❄️' };
const icon = icons[classification] || '❓';

const senalesArr = output.senales_clave || [];
let senales = '';
for (let i = 0; i < senalesArr.length; i++) {
  senales += '<br>• ' + senalesArr[i];
}
if (!senales) senales = '<br>• Sin señales identificadas';

const nombre = output.nombre || 'No especificado';
const email = output.email || 'No especificado';
const telefono = output.telefono || 'No especificado';
const empresa = output.empresa || 'No especificado';
const resumen = output.resumen || 'Sin resumen';
const accion = output.accion_recomendada || 'Sin recomendación';

const html = '<b>📋 Lead Identificado</b><br><br>' +
  '<b>Nombre:</b> ' + nombre + '<br>' +
  '<b>Email:</b> ' + email + '<br>' +
  '<b>Teléfono:</b> ' + telefono + '<br>' +
  '<b>Empresa:</b> ' + empresa + '<br><br>' +
  '<b>📝 Resumen</b><br>' + resumen + '<br><br>' +
  '<b>🎯 Clasificación</b><br>' +
  '<b>Nivel:</b> ' + icon + ' ' + classification.toUpperCase() + '<br>' +
  '<b>Puntuación:</b> ' + score + '/10<br><br>' +
  '<b>💡 Señales Clave</b><br>' + senales + '<br><br>' +
  '<b>➡️ Acción Recomendada</b><br>' + accion;

return [{
  json: Object.assign({}, output, {
    telegramHtml: html,
    chatId: $('Validate & Serialize Payload').first().json.chatId
  })
}];
